window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ead9b22352e143d4"]={"versions": [{"id": "FIG-ead9b22352e143d4", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Prozessdiagramm (Software & Systems Process Engineering Metamodel) für die Methodik der AUTOSAR-Timing-Analyse. Das Diagramm modelliert den ECU-spezifischen Anwendungsfall „Debug Timing“ im Kontext des übergeordneten Teilprozesses <code>Timing_Analysis_for_ECU</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Task Definition</strong>: <code>Perform Implementation-Based Timing Analysis</code> (Aufgabenknoten / SPEM-Task).</li>\n<li><strong>Work Products (Input / Output)</strong>:</li>\n<li><code>Set of Test Conditions</code> (Work Product, eingehend via Stereotyp <code>«input»</code>).</li>\n<li><code>Implementation</code> (Work Product, eingehend via Stereotyp <code>«input»</code>).</li>\n<li><code>Timing Analysis Report</code> (Work Product, ausgehend via Stereotyp <code>«output»</code>).</li>\n<li><strong>Activity / Sub-Process Use Case</strong>:</li>\n<li><code>Optimize timing of an ECU</code> (Aktivität mit Stereotyp <code>«ecu»</code>, referenziert <code>(from Timing_Analysis_for_ECU)</code>).</li>\n<li><strong>Notiz / Constraint</strong>:</li>\n<li>Kommentarfeld <code>modify the conditions for timing analysis until timing problem can be observed</code>, über gestrichelte Assoziationslinien mit <code>Set of Test Conditions</code> und <code>Timing Analysis Report</code> verknüpft.</li>\n<li><strong>Beziehungen</strong>:</li>\n<li>Gerichtete Kontroll-/Datenflusskanten mit Stereotypen <code>«input»</code> und <code>«output»</code> zwischen den Artefakten und dem Task.</li>\n<li>Gestrichelte Abhängigkeitskante (Dependency / Tracing) vom <code>Timing Analysis Report</code> zur Aktivität <code>Optimize timing of an ECU</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Als Eingangswerkprodukte gehen die <code>Implementation</code> (ECU-Implementierungsartefakte) und das <code>Set of Test Conditions</code> (Test- bzw. Randbedingungen) in den Task <code>Perform Implementation-Based Timing Analysis</code> ein.</li>\n<li>Der Task <code>Perform Implementation-Based Timing Analysis</code> führt die implementierungsbasierte Zeitanalyse durch und generiert als Ergebnis den <code>Timing Analysis Report</code>.</li>\n<li>Es besteht eine iterative Rückkopplungsschleife (beschrieben durch die Notiz): Die Bedingungen für die Zeitanalyse (<code>Set of Test Conditions</code>) werden auf Basis der Ergebnisse (<code>Timing Analysis Report</code>) modifiziert, bis das Timing-Problem reproduzierbar beobachtet werden kann.</li>\n<li>Nach erfolgreicher Analyse und Dokumentation dient der <code>Timing Analysis Report</code> als Grundlage für die nachgelagerte Aktivität <code>Optimize timing of an ECU</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Prozessschritt ist methodischer Bestandteil des AUTOSAR-Timing-Leitfadens (TR TimingAnalysis) zur ECU-Fehlerdiagnose. Entwickler und Integratoren müssen bei Timing-Verletzungen schrittweise Test- und Stimulationsmuster (<code>Set of Test Conditions</code>) anpassen, um sporadische oder lastabhängige Timing-Fehler in der Implementierung zu isolieren, bevor Optimierungsmaßnahmen an der ECU durchgeführt werden können.</p>"}, {"id": "FIG-b41b45fcf0c0a425", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Prozessdiagramm (Software & Systems Process Engineering Metamodel) für die Methodik der AUTOSAR-Timing-Analyse. Das Diagramm modelliert den ECU-spezifischen Anwendungsfall „Debug Timing“ im Kontext des übergeordneten Teilprozesses <code>Timing_Analysis_for_ECU</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Task Definition</strong>: <code>Perform Implementation-Based Timing Analysis</code> (Aufgabenknoten / SPEM-Task).</li>\n<li><strong>Work Products (Input / Output)</strong>:</li>\n<li><code>Set of Test Conditions</code> (Work Product, eingehend via Stereotyp <code>«input»</code>).</li>\n<li><code>Implementation</code> (Work Product, eingehend via Stereotyp <code>«input»</code>).</li>\n<li><code>Timing Analysis Report</code> (Work Product, ausgehend via Stereotyp <code>«output»</code>).</li>\n<li><strong>Activity / Sub-Process Use Case</strong>:</li>\n<li><code>Optimize timing of an ECU</code> (Aktivität mit Stereotyp <code>«ecu»</code>, referenziert <code>(from Timing_Analysis_for_ECU)</code>).</li>\n<li><strong>Notiz / Constraint</strong>:</li>\n<li>Kommentarfeld <code>modify the conditions for timing analysis until timing problem can be observed</code>, über gestrichelte Assoziationslinien mit <code>Set of Test Conditions</code> und <code>Timing Analysis Report</code> verknüpft.</li>\n<li><strong>Beziehungen</strong>:</li>\n<li>Gerichtete Kontroll-/Datenflusskanten mit Stereotypen <code>«input»</code> und <code>«output»</code> zwischen den Artefakten und dem Task.</li>\n<li>Gestrichelte Abhängigkeitskante (Dependency / Tracing) vom <code>Timing Analysis Report</code> zur Aktivität <code>Optimize timing of an ECU</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Als Eingangswerkprodukte gehen die <code>Implementation</code> (ECU-Implementierungsartefakte) und das <code>Set of Test Conditions</code> (Test- bzw. Randbedingungen) in den Task <code>Perform Implementation-Based Timing Analysis</code> ein.</li>\n<li>Der Task <code>Perform Implementation-Based Timing Analysis</code> führt die implementierungsbasierte Zeitanalyse durch und generiert als Ergebnis den <code>Timing Analysis Report</code>.</li>\n<li>Es besteht eine iterative Rückkopplungsschleife (beschrieben durch die Notiz): Die Bedingungen für die Zeitanalyse (<code>Set of Test Conditions</code>) werden auf Basis der Ergebnisse (<code>Timing Analysis Report</code>) modifiziert, bis das Timing-Problem reproduzierbar beobachtet werden kann.</li>\n<li>Nach erfolgreicher Analyse und Dokumentation dient der <code>Timing Analysis Report</code> als Grundlage für die nachgelagerte Aktivität <code>Optimize timing of an ECU</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Prozessschritt ist methodischer Bestandteil des AUTOSAR-Timing-Leitfadens (TR TimingAnalysis) zur ECU-Fehlerdiagnose. Entwickler und Integratoren müssen bei Timing-Verletzungen schrittweise Test- und Stimulationsmuster (<code>Set of Test Conditions</code>) anpassen, um sporadische oder lastabhängige Timing-Fehler in der Implementierung zu isolieren, bevor Optimierungsmaßnahmen an der ECU durchgeführt werden können.</p>"}], "trans": [{"from": "FIG-ead9b22352e143d4", "to": "FIG-b41b45fcf0c0a425", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
